class Solution:
    def maxPalindromes(self, s: str, k: int) -> int:
        n = len(s)
        isPal = [[False]*n for _ in range(n)]
        for i in range(n-1, -1, -1):
            for j in range(i, n):
                isPal[i][j] = s[i] == s[j] and (j - i < 2 or isPal[i+1][j-1])
        ans = i = 0
        while i + k <= n:
            j = i + k - 1
            while j < n and not isPal[i][j]:
                j += 1
            if j < n:
                ans += 1
                i = j + 1
            else:
                i += 1
        return ans

