class Solution {
public:
    int maxPalindromes(string s, int k) {
        int n = s.size();
        vector<vector<bool>> P(n, vector<bool>(n, false));
        for (int i = n - 1; i >= 0; i--)
            for (int j = i; j < n; j++)
                P[i][j] = s[i] == s[j] && (j - i < 2 || P[i+1][j-1]);
        int ans = 0, i = 0;
        while (i + k <= n) {
            int j = i + k - 1;
            while (j < n && !P[i][j]) j++;
            if (j < n) { ans++; i = j + 1; }
            else i++;
        }
        return ans;
    }
};

