class Solution:
    def maxPalindromes(self, s: str, k: int) -> int:
        n = len(s)
        def pal(l, r):
            while l >= 0 and r < n and s[l] == s[r]:
                l -= 1; r += 1
            return r - l - 1
        ans = i = 0
        while i + k <= n:
            if pal(i, i + k - 1) >= k:
                ans += 1; i += k
            elif i + k + 1 <= n and pal(i, i + k) >= k + 1:
                ans += 1; i += k + 1
            else:
                i += 1
        return ans

